    (NEWID(), source.Codigo, NULL, source.Nombre, source.Descripcion, source.Familia, source.TipoProduccion, NULL, source.TieneTemplate, source.EsFirmaConjunta, source.EsFirmaExterna, source.TieneToken, source.EsEspecial, source.EsNotificable, source.EsConfidencial, CAST(0 AS bit), CAST(1 AS bit));"
